/** The exact message a wallet signs to sign in; the server rebuilds it to verify. */
export function signInMessage(address: string, issuedAt: string, title = 'Pangs Rally Beta Season sign-in'): string {
  return [
    title,
    '',
    `Wallet: ${address}`,
    `Issued: ${issuedAt}`,
    '',
    'Signing proves you own this wallet. It is free: no gas, no transaction.',
  ].join('\n');
}

export function pointsFor(position: number): number {
  return POINTS_BY_POSITION[position - 1] ?? 0;
}

export function shortWallet(wallet: string): string {
  return wallet.length > 12 ? `${wallet.slice(0, 6)}…${wallet.slice(-4)}` : wallet;
}

/** Player names: 3-16 letters, digits or _, starting with a letter. */
export const USERNAME_MIN = 3;
export const USERNAME_MAX = 16;
// Bot call names are reserved so a player never looks like a bot, and team words so nobody looks like staff.
const RESERVED_NAMES = new Set([
  ...CALL_NAMES.map(n => n.toLowerCase()),
  'admin', 'administrator', 'mod', 'moderator', 'support', 'staff', 'team', 'official', 'dev', 'developer',
  'pangs', 'pang', 'pangsrally', 'pangs_rally', 'rally', 'bot', 'system', 'owner', 'metamask', 'robinhood',
]);
const BLOCKED_PARTS = ['fuck', 'shit', 'bitch', 'cunt', 'nigg', 'fag', 'rape', 'nazi', 'hitler', 'porn', 'whore', 'slut', 'dick', 'pussy', 'retard'];

/** The cleaned name, or a reason it cannot be used (checked in the browser and again on the server). */
export function checkUsername(raw: string): { name: string } | { error: string } {
  const name = raw.trim();
  if (name.length < USERNAME_MIN || name.length > USERNAME_MAX) return { error: `Use ${USERNAME_MIN} to ${USERNAME_MAX} characters.` };
  if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(name)) return { error: 'Start with a letter; then use letters, numbers or _.' };
  const lower = name.toLowerCase();
  if (/^0x/.test(lower) || RESERVED_NAMES.has(lower) || BLOCKED_PARTS.some(p => lower.replace(/_/g, '').includes(p))) {
    return { error: 'This name is not available.' };
  }
  return { name };
}

/** Streak badges: earned by racing this many UTC days in a row. Earned once, kept for good. */
export const STREAK_BADGES = [
  { days: 3, name: 'On a Roll', ball: 'brown' },
  { days: 7, name: 'Hard Shell', ball: 'silver' },
  { days: 14, name: 'Iron Scales', ball: 'gold' },
  { days: 30, name: 'Unbroken', ball: 'aurora' },
] as const;

export interface Streak {
  /** days in a row up to today, or up to yesterday while today is still open */
  current: number;
  /** longest run ever; badges follow this, so a broken streak never takes one away */
  best: number;
  ranToday: boolean;
  /** the last 7 UTC days, oldest first, today last */
  week: boolean[];
  /** days of the highest badge earned, 0 for none */
  badge: number;
}

const DAY_MS = 86_400_000;
const dayNumber = (day: string) => Math.floor(Date.parse(`${day.slice(0, 10)}T00:00:00Z`) / DAY_MS);

/** The streak from the UTC days (YYYY-MM-DD) a wallet raced on. A day counts once, however many races it had. */
export function streakFor(days: string[], today: string): Streak {
  const raced = new Set(days.map(dayNumber));
  const now = dayNumber(today);
  const ordered = [...raced].sort((a, b) => a - b);
  let best = 0;
  let run = 0;
  ordered.forEach((d, i) => {
    run = i > 0 && d === ordered[i - 1] + 1 ? run + 1 : 1;
    best = Math.max(best, run);
  });
  const ranToday = raced.has(now);
  let current = 0;
  for (let d = ranToday ? now : now - 1; raced.has(d); d--) current++;
  const badge = STREAK_BADGES.reduce((top, b) => (best >= b.days ? b.days : top), 0);
  return { current, best, ranToday, week: Array.from({ length: 7 }, (_, i) => raced.has(now - 6 + i)), badge };
}

/**
 * The 10-racer field for a race. `wallets` are the players in join order;
 * bots fill the remaining lanes. A single-player (bot) race puts the player
 * in a seeded random lane, same as several players in a room.
 */
export function buildTestField(seed: string, wallets: string[], names: Record<string, string> = {}): TestRacer[] {
  const players = wallets.slice(0, FIELD_SIZE).map(w => w.toLowerCase());
  const lanes = assignLanes(seed, players.length);

  // Players race in their Beta pass; bots wear the public teasers in a seeded order.
  const rng = seededRandom(`${seed}:teasers`);
  const botTokens = shuffle(Array.from({ length: PUBLIC_TOKENS }, (_, i) => i + 1), rng);

  const usedNames = new Set<string>();
  const field: (TestRacer | null)[] = Array(FIELD_SIZE).fill(null);
  players.forEach((wallet, i) => {
    field[lanes[i] - 1] = betaRacer(`p-${wallet}`, names[wallet] ?? shortWallet(wallet), wallet);
  });
  let b = 0;
  for (let lane = 0; lane < FIELD_SIZE; lane++) {
    if (field[lane]) continue;
    const tokenId = botTokens[b];
    const name = callNameForToken(tokenId, usedNames);
    usedNames.add(name);
    field[lane] = racer(`bot-${b}`, name, tokenId);
    b++;
  }
  return field as TestRacer[];
}

/** Runs the race to the finish. Same seed + field → same result, in the browser and on the server. */
export function runTestRace(seed: string, field: RacerInput[], terrain: string): TestRaceResult[] {
  const sim = new RaceSimulation(seed, field, { distance: DEFAULT_RACE_DISTANCE, terrain });
  sim.start();
  for (let guard = 0; !sim.finished && guard < 200_000; guard++) sim.step(1 / 60);
  return sim.racers.map(r => ({ id: r.id, position: r.position, finishTime: r.finishTime }));
}

function racer(id: string, name: string, tokenId: number, wallet?: string): TestRacer {
  return {
    id,
    name,
    tokenId,
    body: TEASER_BODIES[tokenId] ?? 'Brown',
    avatarUrl: `/nft-images/${tokenId}.webp`,
    isPlayer: false,
    stats: { ...TEST_STATS },
    terrainAffinity: null,
    ...(wallet ? { wallet } : {}),
  };
}

/** The test season pass racer (scripts/make-beta-nft.mjs, ball from make-beta-ball.mjs). tokenId 0 = not a collection token. */
export const BETA_RACER_ART = '/beta/beta-racer.webp';

function betaRacer(id: string, name: string, wallet: string): TestRacer {
  return { ...racer(id, name, 0, wallet), body: 'Beta', avatarUrl: BETA_RACER_ART };
}

/** 1-based lanes for the players, in join order. */
function assignLanes(seed: string, count: number): number[] {
  const lanes = shuffle(Array.from({ length: FIELD_SIZE }, (_, i) => i + 1), seededRandom(seed));
  return lanes.slice(0, count);
}

/** Small seeded RNG (FNV-1a hash + xorshift) so this module needs no extra dependencies. */
function seededRandom(seed: string): () => number {
  let s = 2166136261;
  for (let i = 0; i < seed.length; i++) s = Math.imul(s ^ seed.charCodeAt(i), 16777619);
  return () => {
    s ^= s << 13; s ^= s >>> 17; s ^= s << 5;
    return (s >>> 0) / 4294967296;
  };
}

function shuffle<T>(items: T[], rng: () => number): T[] {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
